from collections import deque

def sliding_max(xs, w):
    if w < 1:
        raise ValueError("w must be >= 1")
    n = len(xs)
    if w > n:
        return []
    dq = deque()  # stores indices, values decreasing
    result = []
    for i, x in enumerate(xs):
        while dq and xs[dq[-1]] <= x:
            dq.pop()
        dq.append(i)
        if dq[0] <= i - w:
            dq.popleft()
        if i >= w - 1:
            result.append(xs[dq[0]])
    return result
```

